1	use std::env;
2	use std::io::Read;
3	use std::process::ExitCode;
4	
5	use hmac::{
6	    Hmac, Mac,
7	    digest::KeyInit,
8	};
9	use sha2::Sha256;
10	
11	const FORMAT_VERSION: u32 = 1;
12	const ALGORITHM: &str = "HMAC-SHA256";
13	/// Domain separator that also records the format version, so tags computed
14	/// by different versions of the encoding can never collide.
15	const DOMAIN_SEPARATOR: &[u8] = b"authnote-sign-v1";
16	
17	fn main() -> ExitCode {
18	    let args: Vec<String> = match decode_args() {
19	        Ok(args) => args,
20	        Err(msg) => {
21	            eprintln!("authnote: {msg}");
22	            return ExitCode::from(2);
23	        }
24	    };
25	    match args.first().map(String::as_str) {
26	        Some("--version") if args.len() == 1 => {
27	            println!("authnote 0.1.0");
28	            ExitCode::SUCCESS
29	        }
30	        Some("sign") => sign(&args[1..]),
31	        Some("verify") => verify(&args[1..]),
32	        _ => {
33	            eprintln!("Usage: authnote --version");
34	            eprintln!(
35	                "       authnote sign --key HEX --key-id ID --key-version N [--field TEXT]..."
36	            );
37	            eprintln!("       authnote verify --key HEX");
38	            ExitCode::from(2)
39	        }
40	    }
41	}
