65	struct SignOptions {
66	    key: String,
67	    key_id: String,
68	    key_version: String,
69	    fields: Vec<String>,
70	}
71	
72	fn sign(args: &[String]) -> ExitCode {
73	    match parse_sign_args(args).and_then(validate_sign_args) {
74	        Ok(opts) => {
75	            let key_bytes = decode_hex(&opts.key).expect("key was validated as hex");
76	            let key_version: u32 = opts.key_version.parse().expect("version was validated");
77	            let message = encode_message(&opts.key_id, key_version, &opts.fields);
78	            let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
79	                .expect("HMAC accepts keys of any length");
80	            mac.update(&message);
81	            let tag = mac.finalize().into_bytes();
82	
83	            let fields_json = opts
84	                .fields
85	                .iter()
86	                .map(|f| format!("\"{}\"", json_escape(f)))
87	                .collect::<Vec<_>>()
88	                .join(",");
89	            println!(
90	                "{{\"format\":{FORMAT_VERSION},\"algorithm\":\"{ALGORITHM}\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
91	                json_escape(&opts.key_id),
92	                key_version,
93	                fields_json,
94	                hex_encode(&tag),
95	            );
96	            ExitCode::SUCCESS
97	        }
98	        Err(msg) => {
99	            eprintln!("authnote sign: {msg}");
100	            ExitCode::from(2)
101	        }
102	    }
103	}
104	
105	fn parse_sign_args(args: &[String]) -> Result<SignOptions, String> {
106	    let mut key: Option<String> = None;
107	    let mut key_id: Option<String> = None;
108	    let mut key_version: Option<String> = None;
109	    let mut fields: Vec<String> = Vec::new();
110	
111	    let set_once = |slot: &mut Option<String>, name: &str, value: String| -> Result<(), String> {
112	        if slot.is_some() {
113	            return Err(format!("option {name} must be given exactly once"));
114	        }
115	        *slot = Some(value);
116	        Ok(())
117	    };
118	
119	    let mut i = 0;
120	    while i < args.len() {
121	        let arg = &args[i];
122	        // Support both "--opt value" and "--opt=value" forms.
123	        let (name, inline_value) = match arg.split_once('=') {
124	            Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
125	            _ => (arg.as_str(), None),
126	        };
127	        let take_value = |i: &mut usize| -> Result<String, String> {
128	            if let Some(v) = inline_value {
129	                return Ok(v);
130	            }
131	            *i += 1;
132	            args.get(*i)
133	                .cloned()
134	                .ok_or_else(|| format!("option {name} requires a value"))
135	        };
136	        match name {
137	            "--key" => {
138	                let v = take_value(&mut i)?;
139	                set_once(&mut key, "--key", v)?;
140	            }
141	            "--key-id" => {
142	                let v = take_value(&mut i)?;
143	                set_once(&mut key_id, "--key-id", v)?;
144	            }
145	            "--key-version" => {
146	                let v = take_value(&mut i)?;
147	                set_once(&mut key_version, "--key-version", v)?;
148	            }
149	            "--field" => {
150	                let v = take_value(&mut i)?;
151	                fields.push(v);
152	            }
153	            _ => {
154	                // Never echo the unrecognized argument itself: it may be a
155	                // misplaced secret (e.g. a key value whose option name was
156	                // mistyped or whose value was consumed by another option).
157	                return Err(
158	                    "unrecognized option or argument (known options: --key, --key-id, --key-version, --field)"
159	                        .to_string(),
160	                );
161	            }
162	        }
163	        i += 1;
164	    }
165	
166	    let key = key.ok_or("missing required option --key")?;
167	    let key_id = key_id.ok_or("missing required option --key-id")?;
168	    let key_version = key_version.ok_or("missing required option --key-version")?;
169	    Ok(SignOptions {
170	        key,
171	        key_id,
172	        key_version,
173	        fields,
174	    })
175	}
176	
177	fn validate_sign_args(opts: SignOptions) -> Result<SignOptions, String> {
178	    // Never echo the key back in error messages.
179	    validate_key_hex(&opts.key)?;
180	    if opts.key_id.is_empty() {
181	        return Err("--key-id must not be empty".to_string());
182	    }
183	    let valid_version = !opts.key_version.is_empty()
184	        && opts.key_version.bytes().all(|b| b.is_ascii_digit())
185	        && opts
186	            .key_version
187	            .parse::<u64>()
188	            .is_ok_and(|v| (1..=u32::MAX as u64).contains(&v));
189	    if !valid_version {
190	        return Err("--key-version must be a decimal integer between 1 and 4294967295".to_string());
191	    }
192	    Ok(opts)
193	}
