195	/// Shared key validation for `sign` and `verify`: non-empty even-length hex.
196	/// The rejected value is never included in the message.
197	fn validate_key_hex(key: &str) -> Result<(), String> {
198	    if key.is_empty() || key.len() % 2 != 0 || !key.bytes().all(|b| b.is_ascii_hexdigit()) {
199	        return Err("--key must be a non-empty, even-length hexadecimal string".to_string());
200	    }
201	    Ok(())
202	}
