208	fn verify(args: &[String]) -> ExitCode {
209	    // The option grammar for verify mirrors sign: "--opt value" or
210	    // "--opt=value", exactly one --key, no other options. Values that fail are
211	    // never echoed (they could be a mistyped secret).
212	    let mut key: Option<String> = None;
213	    let mut i = 0;
214	    let parse = (|| -> Result<String, String> {
215	        while i < args.len() {
216	            let arg = &args[i];
217	            let (name, inline_value) = match arg.split_once('=') {
218	                Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
219	                _ => (arg.as_str(), None),
220	            };
221	            if name != "--key" {
222	                return Err(
223	                    "unrecognized option or argument (the only known option is --key)"
224	                        .to_string(),
225	                );
226	            }
227	            let value = if let Some(v) = inline_value {
228	                v
229	            } else {
230	                i += 1;
231	                match args.get(i) {
232	                    Some(v) => v.clone(),
233	                    None => return Err("option --key requires a value".to_string()),
234	                }
235	            };
236	            if key.is_some() {
237	                return Err("option --key must be given exactly once".to_string());
238	            }
239	            key = Some(value);
240	            i += 1;
241	        }
242	        let key = key.ok_or("missing required option --key")?;
243	        validate_key_hex(&key)?;
244	        Ok(key)
245	    })();
246	
247	    let key_hex = match parse {
248	        Ok(key) => key,
249	        Err(msg) => {
250	            eprintln!("authnote verify: {msg}");
251	            return ExitCode::from(2);
252	        }
253	    };
254	
255	    // Read the whole standard input. It must be one JSON record and nothing
256	    // else; trailing non-whitespace is a malformed invocation, not a mismatch.
257	    let mut input = Vec::new();
258	    if let Err(e) = std::io::stdin().read_to_end(&mut input) {
259	        eprintln!("authnote verify: failed to read standard input: {e}");
260	        return ExitCode::from(2);
261	    }
262	
263	    let outcome = verify_input(&input, &key_hex);
264	    match outcome {
265	        VerifyOutcome::Valid => {
266	            println!("{{\"valid\":true}}");
267	            ExitCode::SUCCESS
268	        }
269	        VerifyOutcome::Mismatch => {
270	            println!("{{\"valid\":false}}");
271	            ExitCode::from(1)
272	        }
273	        VerifyOutcome::Invalid(msg) => {
274	            eprintln!("authnote verify: {msg}");
275	            ExitCode::from(2)
276	        }
277	    }
278	}
279	
280	#[derive(Debug)]
281	enum VerifyOutcome {
282	    Valid,
283	    Mismatch,
284	    Invalid(String),
285	}
286	
287	fn verify_input(input: &[u8], key_hex: &str) -> VerifyOutcome {
288	    let text = match std::str::from_utf8(input) {
289	        Ok(t) => t,
290	        // Still parse to distinguish a structurally invalid record from a
291	        // record whose text merely contains bytes Rust rejects; JSON itself
292	        // forbids raw non-UTF-8, so this is always "corrupt input" here.
293	        Err(_) => return VerifyOutcome::Invalid("input is not valid UTF-8 JSON text".to_string()),
294	    };
295	
296	    let value = match json::parse_single(text) {
297	        Ok(v) => v,
298	        Err(msg) => return VerifyOutcome::Invalid(msg),
299	    };
300	    let record = match record_from_json(&value) {
301	        Ok(r) => r,
302	        Err(msg) => return VerifyOutcome::Invalid(msg),
303	    };
304	
305	    let key_bytes = decode_hex(key_hex).expect("key was validated as hex");
306	    let message = encode_message(&record.key_id, record.key_version, &record.fields);
307	    let mut mac = <Hmac<Sha256> as KeyInit>::new_from_slice(&key_bytes)
308	        .expect("HMAC accepts keys of any length");
309	    mac.update(&message);
310	
311	    let expected_tag = mac.finalize().into_bytes();
312	    let given_tag = &record.tag;
313	
314	    // Both sides are 32 bytes; compare in constant time so a mismatch cannot
315	    // be recovered one byte at a time through timing.
316	    debug_assert_eq!(expected_tag.len(), given_tag.len());
317	    if expected_tag.len() != given_tag.len() {
318	        return VerifyOutcome::Mismatch;
319	    }
320	    let mut diff = 0u8;
321	    for (a, b) in expected_tag.iter().zip(given_tag.iter()) {
322	        diff |= a ^ b;
323	    }
324	    if diff == 0 {
325	        VerifyOutcome::Valid
326	    } else {
327	        VerifyOutcome::Mismatch
328	    }
329	}
