331	/// Decode the tag as exactly 32 bytes of case-insensitive hexadecimal.
332	fn decode_tag(s: &str) -> Result<Vec<u8>, String> {
333	    if s.len() != 64 || !s.bytes().all(|b| b.is_ascii_hexdigit()) {
334	        return Err("tag must be exactly 64 hexadecimal characters (32 bytes)".to_string());
335	    }
336	    decode_hex(s).map_err(|e| format!("tag is not valid hexadecimal: {e}"))
337	}
338	
339	struct AuthRecord {
340	    key_id: String,
341	    key_version: u32,
342	    fields: Vec<String>,
343	    tag: Vec<u8>,
344	}
345	
346	/// Validate the decoded JSON value as exactly one format-1 authentication
347	/// record and pull out the authenticated fields. Structural problems (missing
348	/// members, wrong types, duplicates inside `fields`, ...) are caller errors:
349	/// they must produce exit 2, never a `{"valid":false}` mismatch result.
350	fn record_from_json(value: &json::JsonValue) -> Result<AuthRecord, String> {
351	    let obj = match value {
352	        json::JsonValue::Object(entries) => entries,
353	        _ => return Err("record must be a single JSON object".to_string()),
354	    };
355	
356	    // Require precisely the six documented members, each present exactly once;
357	    // the parser already rejects duplicate member names, and an empty object
358	    // naturally fails the "missing required member" checks below.
359	    let mut format: Option<&json::JsonValue> = None;
360	    let mut algorithm: Option<&json::JsonValue> = None;
361	    let mut key_id: Option<&json::JsonValue> = None;
362	    let mut key_version: Option<&json::JsonValue> = None;
363	    let mut fields: Option<&json::JsonValue> = None;
364	    let mut tag: Option<&json::JsonValue> = None;
365	    for (name, val) in obj {
366	        let slot = match name.as_str() {
367	            "format" => &mut format,
368	            "algorithm" => &mut algorithm,
369	            "key_id" => &mut key_id,
370	            "key_version" => &mut key_version,
371	            "fields" => &mut fields,
372	            "tag" => &mut tag,
373	            // Do not echo the unknown member name: it comes from the input
374	            // record, which error messages must never quote back.
375	            _ => return Err("record contains an unexpected member".to_string()),
376	        };
377	        if slot.is_some() {
378	            // The strict parser rejects duplicates already; keep a defense in
379	            // depth without quoting the member name from the input twice.
380	            return Err("record contains a duplicate member".to_string());
381	        }
382	        *slot = Some(val);
383	    }
384	
385	    // Unsupported format/algorithm must be reported as such explicitly: we do
386	    // not silently fall back to the current rules and compute a result.
387	    let format = format.ok_or("record is missing required member \"format\"")?;
388	    match format {
389	        json::JsonValue::Number(n) if *n == i128::from(FORMAT_VERSION) => {}
390	        json::JsonValue::Number(_) => {
391	            return Err("unsupported record format version; only format 1 is supported".to_string())
392	        }
393	        _ => return Err("member \"format\" must be an integer".to_string()),
394	    }
395	
396	    let algorithm = algorithm.ok_or("record is missing required member \"algorithm\"")?;
397	    match algorithm {
398	        json::JsonValue::String(s) if s == ALGORITHM => {}
399	        json::JsonValue::String(_) => {
400	            return Err(
401	                "unsupported algorithm in record; only HMAC-SHA256 is supported".to_string(),
402	            )
403	        }
404	        _ => return Err("member \"algorithm\" must be a string".to_string()),
405	    }
406	
407	    let key_id = key_id.ok_or("record is missing required member \"key_id\"")?;
408	    let key_id = match key_id {
409	        json::JsonValue::String(s) if !s.is_empty() => s.clone(),
410	        json::JsonValue::String(_) => {
411	            return Err("member \"key_id\" must not be empty".to_string())
412	        }
413	        _ => return Err("member \"key_id\" must be a string".to_string()),
414	    };
415	
416	    let key_version = key_version.ok_or("record is missing required member \"key_version\"")?;
417	    let key_version = match key_version {
418	        json::JsonValue::Number(n) => {
419	            if *n < 1 || *n > i128::from(u32::MAX) {
420	                return Err(
421	                    "member \"key_version\" is outside the supported range 1..=4294967295"
422	                        .to_string(),
423	                );
424	            }
425	            *n as u32
426	        }
427	        _ => return Err("member \"key_version\" must be an integer".to_string()),
428	    };
429	
430	    let fields_val = fields.ok_or("record is missing required member \"fields\"")?;
431	    let fields = match fields_val {
432	        json::JsonValue::Array(items) => {
433	            let mut out = Vec::with_capacity(items.len());
434	            for item in items {
435	                match item {
436	                    json::JsonValue::String(s) => out.push(s.clone()),
437	                    _ => {
438	                        return Err(
439	                            "every element of member \"fields\" must be a string".to_string()
440	                        )
441	                    }
442	                }
443	            }
444	            out
445	        }
446	        _ => return Err("member \"fields\" must be an array of strings".to_string()),
447	    };
448	
449	    let tag_val = tag.ok_or("record is missing required member \"tag\"")?;
450	    let tag = match tag_val {
451	        json::JsonValue::String(s) => decode_tag(s)?,
452	        _ => return Err("member \"tag\" must be a string".to_string()),
453	    };
454	
455	    Ok(AuthRecord {
456	        key_id,
457	        key_version,
458	        fields,
459	        tag,
460	    })
461	}
462	
463	/// Canonical byte encoding of the authenticated content.
464	///
465	/// Layout (all integers big-endian, all text UTF-8, no trimming or escaping):
466	///   DOMAIN_SEPARATOR ("authnote-sign-v1", 16 ASCII bytes)
467	///   u64 length of key-id, then key-id bytes
468	///   u32 key version
469	///   u64 field count
470	///   for each field in order: u64 length of field, then field bytes
471	///
472	/// Length prefixes make field boundaries unambiguous: ["ab","c"] and
473	/// ["a","bc"] encode differently, as do zero fields and one empty field.
474	fn encode_message(key_id: &str, key_version: u32, fields: &[String]) -> Vec<u8> {
475	    let mut out = Vec::new();
476	    out.extend_from_slice(DOMAIN_SEPARATOR);
477	    push_len_prefixed(&mut out, key_id.as_bytes());
478	    out.extend_from_slice(&key_version.to_be_bytes());
479	    out.extend_from_slice(&(fields.len() as u64).to_be_bytes());
480	    for field in fields {
481	        push_len_prefixed(&mut out, field.as_bytes());
482	    }
483	    out
484	}
485	
486	fn push_len_prefixed(out: &mut Vec<u8>, bytes: &[u8]) {
487	    out.extend_from_slice(&(bytes.len() as u64).to_be_bytes());
488	    out.extend_from_slice(bytes);
489	}
490	
491	fn decode_hex(s: &str) -> Result<Vec<u8>, String> {
492	    (0..s.len())
493	        .step_by(2)
494	        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).map_err(|e| e.to_string()))
495	        .collect()
496	}
497	
498	fn hex_encode(bytes: &[u8]) -> String {
499	    bytes.iter().map(|b| format!("{b:02x}")).collect()
500	}
501	
502	fn json_escape(s: &str) -> String {
503	    let mut out = String::with_capacity(s.len());
504	    for c in s.chars() {
505	        match c {
506	            '"' => out.push_str("\\\""),
507	            '\\' => out.push_str("\\\\"),
508	            '\n' => out.push_str("\\n"),
509	            '\r' => out.push_str("\\r"),
510	            '\t' => out.push_str("\\t"),
511	            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
512	            c => out.push(c),
513	        }
514	    }
515	    out
516	}
