518	// ---------------------------------------------------------------------------
519	// Strict JSON parser used by `verify`.
520	//
521	// Written by hand so the crate keeps zero third-party runtime dependencies.
522	// Unlike a tolerant parser it enforces every rule the verify contract relies
523	// on: exactly one complete value surrounded only by JSON whitespace, no
524	// duplicate member names within an object, strict number grammar (integers
525	// only, no fractions/exponents/leading zeros), strings decoded per RFC 8259
526	// including surrogate pairs. Anything it cannot parse is a corrupt record
527	// (exit 2), never a mismatch.
528	// ---------------------------------------------------------------------------
529	
530	mod json {
531	    #[derive(Debug, PartialEq)]
532	    pub enum JsonValue {
533	        /// Parsed as an integer because the record grammar has no fractional
534	        /// values; the width comfortably covers u32 and common JSON integers.
535	        Number(i128),
536	        String(String),
537	        Array(Vec<JsonValue>),
538	        /// Members kept in source order; names are unique (parser-enforced).
539	        Object(Vec<(String, JsonValue)>),
540	        // Accepted so documents using them parse, but records containing them
541	        // are rejected structurally by the caller.
542	        Bool(bool),
543	        Null,
544	    }
545	
546	    struct Parser<'a> {
547	        bytes: &'a [u8],
548	        pos: usize,
549	        /// Current object/array nesting depth, capped so adversarial input
550	        /// ("[[[[...")") cannot exhaust the stack and crash the verifier.
551	        depth: usize,
552	    }
553	
554	    /// Far above the depth a real record ever reaches (record → `fields`
555	    /// array → string is depth 2) while staying well within stack limits.
556	    const MAX_DEPTH: usize = 64;
557	
558	    /// Parse exactly one JSON value: optional leading/trailing JSON whitespace
559	    /// is allowed, but any trailing non-whitespace content (including a second
560	    /// object) is an error.
561	    pub fn parse_single(input: &str) -> Result<JsonValue, String> {
562	        let mut p = Parser {
563	            bytes: input.as_bytes(),
564	            pos: 0,
565	            depth: 0,
566	        };
567	        p.skip_ws();
568	        if p.pos == p.bytes.len() {
569	            return Err("input is empty; expected one JSON record".to_string());
570	        }
571	        let value = p.parse_value()?;
572	        p.skip_ws();
573	        if p.pos != p.bytes.len() {
574	            return Err(
575	                "trailing non-whitespace content after record; exactly one JSON object is allowed"
576	                    .to_string(),
577	            );
578	        }
579	        Ok(value)
580	    }
581	
582	    impl<'a> Parser<'a> {
583	        fn skip_ws(&mut self) {
584	            while self.pos < self.bytes.len()
585	                && matches!(self.bytes[self.pos], b' ' | b'\t' | b'\n' | b'\r')
586	            {
587	                self.pos += 1;
588	            }
589	        }
590	
591	        fn peek(&self) -> Option<u8> {
592	            self.bytes.get(self.pos).copied()
593	        }
594	
595	        fn enter_container(&mut self) -> Result<(), String> {
596	            if self.depth >= MAX_DEPTH {
597	                return Err("JSON nesting is too deep".to_string());
598	            }
599	            self.depth += 1;
600	            Ok(())
601	        }
602	
603	        fn parse_value(&mut self) -> Result<JsonValue, String> {
604	            self.skip_ws();
605	            match self.peek() {
606	                Some(b'{') => self.parse_object(),
607	                Some(b'[') => self.parse_array(),
608	                Some(b'"') => Ok(JsonValue::String(self.parse_string()?)),
609	                Some(b't') => self.parse_lit("true", JsonValue::Bool(true)),
610	                Some(b'f') => self.parse_lit("false", JsonValue::Bool(false)),
611	                Some(b'n') => self.parse_lit("null", JsonValue::Null),
612	                Some(c) if c == b'-' || c.is_ascii_digit() => self.parse_number(),
613	                Some(_) => Err("unexpected character while parsing JSON".to_string()),
614	                None => Err("unexpected end of JSON input".to_string()),
615	            }
616	        }
617	
618	        fn parse_lit(&mut self, lit: &str, value: JsonValue) -> Result<JsonValue, String> {
619	            if self.bytes[self.pos..].starts_with(lit.as_bytes()) {
620	                self.pos += lit.len();
621	                Ok(value)
622	            } else {
623	                Err("malformed JSON literal".to_string())
624	            }
625	        }
626	
627	        fn parse_object(&mut self) -> Result<JsonValue, String> {
628	            self.enter_container()?;
629	            let result = self.parse_object_inner();
630	            self.depth -= 1;
631	            result
632	        }
633	
634	        fn parse_object_inner(&mut self) -> Result<JsonValue, String> {
635	            self.pos += 1; // '{'
636	            let mut entries: Vec<(String, JsonValue)> = Vec::new();
637	            self.skip_ws();
638	            if self.peek() == Some(b'}') {
639	                self.pos += 1;
640	                return Ok(JsonValue::Object(entries));
641	            }
642	            loop {
643	                self.skip_ws();
644	                if self.peek() != Some(b'"') {
645	                    return Err("expected a string member name in JSON object".to_string());
646	                }
647	                let name = self.parse_string()?;
648	                self.skip_ws();
649	                if self.peek() != Some(b':') {
650	                    return Err("expected ':' after JSON member name".to_string());
651	                }
652	                self.pos += 1;
653	                let value = self.parse_value()?;
654	                if entries.iter().any(|(n, _)| *n == name) {
655	                    return Err("JSON object contains a duplicate member".to_string());
656	                }
657	                entries.push((name, value));
658	                self.skip_ws();
659	                match self.peek() {
660	                    Some(b',') => {
661	                        self.pos += 1;
662	                    }
663	                    Some(b'}') => {
664	                        self.pos += 1;
665	                        break;
666	                    }
667	                    Some(_) => return Err("expected ',' or '}}' in JSON object".to_string()),
668	                    None => return Err("unterminated JSON object".to_string()),
669	                }
670	            }
671	            Ok(JsonValue::Object(entries))
672	        }
673	
674	        fn parse_array(&mut self) -> Result<JsonValue, String> {
675	            self.enter_container()?;
676	            let result = self.parse_array_inner();
677	            self.depth -= 1;
678	            result
679	        }
680	
681	        fn parse_array_inner(&mut self) -> Result<JsonValue, String> {
682	            self.pos += 1; // '['
683	            let mut items = Vec::new();
684	            self.skip_ws();
685	            if self.peek() == Some(b']') {
686	                self.pos += 1;
687	                return Ok(JsonValue::Array(items));
688	            }
689	            loop {
690	                items.push(self.parse_value()?);
691	                self.skip_ws();
692	                match self.peek() {
693	                    Some(b',') => {
694	                        self.pos += 1;
695	                        self.skip_ws();
696	                    }
697	                    Some(b']') => {
698	                        self.pos += 1;
699	                        break;
700	                    }
701	                    Some(_) => return Err("expected ',' or ']' in JSON array".to_string()),
702	                    None => return Err("unterminated JSON array".to_string()),
703	                }
704	            }
705	            Ok(JsonValue::Array(items))
706	        }
707	
708	        fn parse_string(&mut self) -> Result<String, String> {
709	            self.pos += 1; // opening quote
710	            let mut out = String::new();
711	            loop {
712	                match self.peek() {
713	                    None => return Err("unterminated JSON string".to_string()),
714	                    Some(b'"') => {
715	                        self.pos += 1;
716	                        break;
717	                    }
718	                    Some(b'\\') => {
719	                        self.pos += 1;
720	                        let esc = self
721	                            .peek()
722	                            .ok_or("unterminated JSON escape sequence")?;
723	                        self.pos += 1;
724	                        match esc {
725	                            b'"' => out.push('"'),
726	                            b'\\' => out.push('\\'),
727	                            b'/' => out.push('/'),
728	                            b'b' => out.push('\u{0008}'),
729	                            b'f' => out.push('\u{000c}'),
730	                            b'n' => out.push('\n'),
731	                            b'r' => out.push('\r'),
732	                            b't' => out.push('\t'),
733	                            b'u' => {
734	                                let hi = self.parse_hex4()?;
735	                                let c = if (0xD800..=0xDBFF).contains(&hi) {
736	                                    // High surrogate must be followed by "\uXXXX"
737	                                    // low surrogate; lone surrogates are invalid.
738	                                    if self.peek() != Some(b'\\') {
739	                                        return Err(
740	                                            "lone UTF-16 high surrogate in JSON string".to_string()
741	                                        );
742	                                    }
743	                                    self.pos += 1;
744	                                    if self.peek() != Some(b'u') {
745	                                        return Err(
746	                                            "bad surrogate pair escape in JSON string".to_string()
747	                                        );
748	                                    }
749	                                    self.pos += 1;
750	                                    let lo = self.parse_hex4()?;
751	                                    if !(0xDC00..=0xDFFF).contains(&lo) {
752	                                        return Err(
753	                                            "low surrogate out of range in JSON string".to_string()
754	                                        );
755	                                    }
756	                                    char::from_u32(0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00))
757	                                        .ok_or("invalid surrogate pair in JSON string")?
758	                                } else if (0xDC00..=0xDFFF).contains(&hi) {
759	                                    return Err(
760	                                        "lone UTF-16 low surrogate in JSON string".to_string()
761	                                    );
762	                                } else {
763	                                    char::from_u32(hi)
764	                                        .ok_or("invalid unicode escape in JSON string")?
765	                                };
766	                                out.push(c);
767	                            }
768	                            _ => {
769	                                return Err("invalid escape sequence in JSON string".to_string())
770	                            }
771	                        }
772	                    }
773	                    Some(c) if c < 0x20 => {
774	                        return Err("unescaped control character in JSON string".to_string())
775	                    }
776	                    Some(_) => {
777	                        // Copy one whole UTF-8 scalar at a time, validating that
778	                        // the raw bytes really are UTF-8 (the surrounding input
779	                        // is &str so this cannot fail, but keep the boundary
780	                        // explicit rather than slicing mid-char).
781	                        let start = self.pos;
782	                        self.pos += 1;
783	                        while self.pos < self.bytes.len() {
784	                            let b = self.bytes[self.pos];
785	                            if b == b'"' || b == b'\\' || b < 0x20 {
786	                                break;
787	                            }
788	                            self.pos += 1;
789	                        }
790	                        let chunk = std::str::from_utf8(&self.bytes[start..self.pos])
791	                            .map_err(|_| "invalid UTF-8 inside JSON string".to_string())?;
792	                        out.push_str(chunk);
793	                    }
794	                }
795	            }
796	            Ok(out)
797	        }
798	
799	        fn parse_hex4(&mut self) -> Result<u32, String> {
800	            let mut v = 0u32;
801	            for _ in 0..4 {
802	                if self.peek().is_none() {
803	                    return Err("truncated \\u escape in JSON string".to_string());
804	                }
805	                let c = self.peek().unwrap();
806	                if !(c as char).is_ascii_hexdigit() {
807	                    return Err("bad hexadecimal digit in \\u escape".to_string());
808	                }
809	                let d = (c as char).to_digit(16).unwrap();
810	                self.pos += 1;
811	                v = v * 16 + d;
812	            }
813	            Ok(v)
814	        }
815	
816	        /// Strict RFC 8259 integer grammar. The record format has no fractional
817	        /// values, so `.`/`e` forms are rejected rather than truncated.
818	        fn parse_number(&mut self) -> Result<JsonValue, String> {
819	            let start = self.pos;
820	            if self.peek() == Some(b'-') {
821	                self.pos += 1;
822	            }
823	            match self.peek() {
824	                Some(b'0') => {
825	                    self.pos += 1;
826	                    // A leading zero must not be followed by more digits.
827	                    if matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
828	                        return Err("numbers with leading zeros are not valid JSON".to_string());
829	                    }
830	                }
831	                Some(c) if c.is_ascii_digit() => {
832	                    while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
833	                        self.pos += 1;
834	                    }
835	                }
836	                _ => return Err("malformed JSON number".to_string()),
837	            }
838	            // No fraction or exponent: this grammar only carries integers.
839	            if matches!(self.peek(), Some(b'.' | b'e' | b'E')) {
840	                return Err(
841	                    "record numbers must be integers; fractions and exponents are not accepted"
842	                        .to_string(),
843	                );
844	            }
845	            let text = std::str::from_utf8(&self.bytes[start..self.pos])
846	                .map_err(|_| "invalid UTF-8 in JSON number".to_string())?;
847	            text.parse::<i128>()
848	                .map(JsonValue::Number)
849	                .map_err(|_| "JSON integer is out of supported range".to_string())
850	        }
851	    }
852	}
