918	    /// Build a format-1 record JSON string for the given content, with the
919	    /// correct tag for `key`.
920	    fn record_for(key_hex: &str, key_id: &str, version: u32, fields: &[&str]) -> String {
921	        let tag = sign_tag(key_hex, key_id, version, fields);
922	        let fields_json = fields
923	            .iter()
924	            .map(|f| format!("\"{}\"", json_escape(f)))
925	            .collect::<Vec<_>>()
926	            .join(",");
927	        format!(
928	            "{{\"format\":1,\"algorithm\":\"HMAC-SHA256\",\"key_id\":\"{}\",\"key_version\":{},\"fields\":[{}],\"tag\":\"{}\"}}",
929	            json_escape(key_id),
930	            version,
931	            fields_json,
932	            tag
933	        )
934	    }
