1067	    fn strict_parser_rules() {
1068	        use json::parse_single;
1069	        assert!(parse_single("{}").is_ok());
1070	        assert!(parse_single(" \n\t {} \r").is_ok());
1071	        assert!(parse_single("{\"a\":1}").is_ok());
1072	        // trailing content, duplicates, fractions/exponents/leading zeros
1073	        assert!(parse_single("{} {}").is_err());
1074	        assert!(parse_single("{}x").is_err());
