1087	            json::JsonValue::String("😀".to_string())
1088	        );
1089	        assert!(parse_single("\"\\ud83d\"").is_err());
1090	        assert!(parse_single("\"\\udc00\"").is_err());
1091	        assert!(parse_single("\"\\x\"").is_err());
1092	        assert!(parse_single("\"\n\"").is_err()); // raw control character
