1	//! End-to-end regression tests for the observable result of `authnote sign`.
2	//!
3	//! These tests execute the built binary and assert on the exact JSON record a
4	//! user receives on stdout/stderr, not just on intermediate HMAC values.
5	//!
6	//! Expected tags are *golden* values: each was computed independently with
7	//! Python's hmac/hashlib/struct straight from the format-1 byte contract in
8	//! README.md (domain separator `authnote-sign-v1`, big-endian u64/u32 length
9	//! prefixes, raw UTF-8 bytes), never derived from this crate's own HMAC code.
10	//! A change that breaks the byte encoding and the JSON output in the same way
11	//! therefore still fails these tests.
12	//!
13	//! The tests parse stdout with the small JSON parser below instead of pulling
14	//! in a third-party dependency, so `Cargo.toml` stays unchanged.
15	
16	use std::process::{Command, Output};
17	
18	// ---------------------------------------------------------------------------
19	// Test harness around the compiled binary.
20	// ---------------------------------------------------------------------------
21	
22	fn authnote() -> Command {
23	    Command::new(env!("CARGO_BIN_EXE_authnote"))
24	}
25	
26	/// Run `sign` with `--field` entries appended in the given order.
27	fn run_sign(key: &str, key_id: &str, version: &str, fields: &[&str]) -> Output {
28	    let mut cmd = authnote();
29	    cmd.arg("sign")
30	        .arg("--key")
31	        .arg(key)
32	        .arg("--key-id")
33	        .arg(key_id)
34	        .arg("--key-version")
35	        .arg(version);
36	    for f in fields {
37	        cmd.arg("--field").arg(f);
38	    }
39	    cmd.output().expect("failed to execute authnote")
40	}
41	
42	/// Run `sign` with a raw argument vector (for error-path cases).
43	fn run_sign_raw(args: &[&str]) -> Output {
44	    let mut cmd = authnote();
45	    cmd.arg("sign");
46	    for a in args {
47	        cmd.arg(a);
48	    }
49	    cmd.output().expect("failed to execute authnote")
50	}
51	
52	/// Run `verify --key <key>` feeding `input` to standard input.
53	fn run_verify(key: &str, input: &[u8]) -> Output {
54	    let mut cmd = authnote();
55	    cmd.arg("verify").arg("--key").arg(key);
56	    use std::io::Write;
57	    use std::process::Stdio;
58	    let mut child = cmd
59	        .stdin(Stdio::piped())
60	        .stdout(Stdio::piped())
61	        .stderr(Stdio::piped())
62	        .spawn()
63	        .expect("failed to spawn authnote");
64	    child
65	        .stdin
66	        .take()
67	        .unwrap()
68	        .write_all(input)
69	        .expect("failed to write record to stdin");
70	    child.wait_with_output().expect("failed to await authnote")
71	}
72	
73	/// Run `verify` with raw arguments and stdin (for option-error cases).
74	fn run_verify_raw(args: &[&str], input: &[u8]) -> Output {
75	    let mut cmd = authnote();
76	    cmd.arg("verify");
77	    for a in args {
78	        cmd.arg(a);
79	    }
80	    use std::io::Write;
81	    use std::process::Stdio;
82	    let mut child = cmd
83	        .stdin(Stdio::piped())
84	        .stdout(Stdio::piped())
85	        .stderr(Stdio::piped())
86	        .spawn()
87	        .expect("failed to spawn authnote");
88	    child
89	        .stdin
90	        .take()
91	        .unwrap()
92	        .write_all(input)
93	        .expect("failed to write to stdin");
94	    child.wait_with_output().expect("failed to await authnote")
95	}
96	
97	/// Sign a record and return its exact stdout bytes (including the newline).
98	fn sign_record_bytes(key: &str, key_id: &str, version: &str, fields: &[&str]) -> Vec<u8> {
99	    run_sign(key, key_id, version, fields).stdout
100	}
101	
102	// ---------------------------------------------------------------------------
103	// verify: success path
104	// ---------------------------------------------------------------------------
105	
106	#[test]
107	fn verify_accepts_the_record_sign_produces() {
108	    let key = "0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b0b";
109	    let record = sign_record_bytes(key, "demo", "3", &["hello", "世界"]);
110	    let out = run_verify(key, &record);
111	    assert_eq!(out.status.code(), Some(0));
112	    assert!(out.stderr.is_empty(), "stderr must be empty, got {:?}", String::from_utf8_lossy(&out.stderr));
113	    assert_eq!(out.stdout, b"{\"valid\":true}\n");
114	}
115	
116	#[test]
117	fn verify_tolerates_reserialization_reordering_and_whitespace() {
118	    let key = "00112233445566778899aabbccddeeff";
119	    let record = sign_record_bytes(key, "kid-名字", "7", &["中文🙂", "x y"]);
120	
121	    // Parse, then emit pretty JSON with members in reverse order.
122	    let body = std::str::from_utf8(&record).unwrap().trim_end_matches('\n');
123	    let parsed = Json::parse(body);
124	    let obj = parsed.as_object();
125	    let mut reordered = String::from("{\n");
126	    for (i, (k, v)) in obj.iter().rev().enumerate() {
127	        if i > 0 {
128	            reordered.push_str(",\n");
129	        }
130	        reordered.push_str(&format!("  {k:?}: "));
131	        reordered.push_str(&json_value_to_text(v));
132	    }
133	    reordered.push_str("\n}");
134	    let padded = format!("  \t\n{reordered}\r\n  ");
135	
136	    let out = run_verify(key, padded.as_bytes());
137	    assert_eq!(out.status.code(), Some(0), "stderr={:?}", String::from_utf8_lossy(&out.stderr));
138	    assert_eq!(out.stdout, b"{\"valid\":true}\n");
139	    assert!(out.stderr.is_empty());
140	}
141	
142	/// Render a parsed Json back into compact JSON (test helper; records contain
143	/// only objects/arrays/strings/integers).
144	fn json_value_to_text(v: &Json) -> String {
145	    fn escape(s: &str) -> String {
146	        let mut out = String::from("\"");
147	        for c in s.chars() {
148	            match c {
149	                '"' => out.push_str("\\\""),
150	                '\\' => out.push_str("\\\\"),
151	                '\n' => out.push_str("\\n"),
152	                '\r' => out.push_str("\\r"),
153	                '\t' => out.push_str("\\t"),
154	                c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
155	                c => out.push(c),
156	            }
157	        }
158	        out.push('"');
159	        out
160	    }
161	    match v {
162	        Json::Str(s) => escape(s),
163	        Json::Num(n) => n.to_string(),
164	        Json::Arr(a) => format!(
165	            "[{}]",
166	            a.iter().map(json_value_to_text).collect::<Vec<_>>().join(",")
167	        ),
168	        Json::Obj(o) => format!(
169	            "{{{}}}",
170	            o.iter()
171	                .map(|(k, v)| format!("{}:{}", escape(k), json_value_to_text(v)))
172	                .collect::<Vec<_>>().join(",")
173	        ),
174	        other => panic!("unexpected value {other:?}"),
175	    }
176	}
177	
178	#[test]
179	fn verify_distinct_encodings_and_unicode_escapes() {
180	    let key = "00ff";
181	    // Zero fields vs one empty field each verify with their own records.
182	    let zero = sign_record_bytes(key, "id", "1", &[]);
183	    let one_empty = sign_record_bytes(key, "id", "1", &[""]);
184	    assert_eq!(run_verify(key, &zero).status.code(), Some(0));
185	    assert_eq!(run_verify(key, &one_empty).status.code(), Some(0));
186	
187	    // A record whose Chinese text is written using \u escapes still verifies:
188	    // verification runs over the decoded text, not the raw JSON spelling.
189	    let rec = sign_record_bytes(key, "id", "1", &["世界"]);
190	    let body = std::str::from_utf8(&rec).unwrap();
