711	/// Successful invocation: exit code 0, empty stderr, one valid record whose
712	/// fields/key-id/version match the inputs and whose tag equals the golden
713	/// value computed independently of this implementation.
714	fn expect_signed_record(
715	    label: &str,
716	    key: &str,
717	    key_id: &str,
718	    version: &str,
719	    fields: &[&str],
720	    golden_tag: &str,
721	) -> Record {
722	    let out = run_sign(key, key_id, version, fields);
723	    assert_eq!(
724	        out.status.code(),
725	        Some(0),
726	        "{label}: expected exit 0, got {:?}, stderr={:?}",
727	        out.status.code(),
728	        String::from_utf8_lossy(&out.stderr)
729	    );
730	    assert!(
731	        out.stderr.is_empty(),
732	        "{label}: stderr must be empty, got {:?}",
733	        String::from_utf8_lossy(&out.stderr)
734	    );
735	
736	    let rec = parse_single_record(&out.stdout);
737	    assert_eq!(rec.tag, golden_tag, "{label}: tag mismatch");
738	    assert_eq!(rec.key_id, key_id, "{label}: key_id mismatch");
739	    assert_eq!(
740	        rec.key_version,
741	        version.parse::<i64>().unwrap(),
742	        "{label}: key_version mismatch"
743	    );
744	    assert_eq!(
745	        rec.fields,
746	        fields.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
747	        "{label}: parsed fields must be character-identical to the inputs"
748	    );
749	
750	    // The raw key is used only for the MAC: it must never appear as a value
751	    // anywhere in the record (compared as a whole string, not a substring, so
752	    // short keys cannot clash with random fragments of the 64-char tag).
753	    let needle = key.to_lowercase();
754	    let mut strings = Vec::new();
755	    rec.raw.strings(&mut strings);
756	    assert!(
757	        strings.iter().all(|s| s.to_lowercase() != needle),
758	        "{label}: raw key material must not be part of the record"
759	    );
760	    rec
761	}
