783	fn unicode_and_json_escapes_round_trip_char_for_char() {
784	    // One field exercising every escape path alongside raw multibyte text:
785	    // Chinese, emoji, double quote, backslash, newline, CR, tab, several
786	    // control characters and DEL. NUL cannot be passed through execve, so the
787	    // C0 range is covered by 0x01/0x08/0x0c/0x1f plus the dedicated
788	    // single-character field test below.
789	    let tricky = "中文🙂\"\\\n\r\t\u{01}\u{08}\u{0c}\u{1f}\u{7f}";
790	    let out = run_sign(
791	        "00112233445566778899aabbccddeeff",
792	        "kid-名字",
793	        "7",
794	        &[tricky],
795	    );
796	    assert_eq!(out.status.code(), Some(0));
797	    assert!(out.stderr.is_empty());
798	    let rec = parse_single_record(&out.stdout);
799	
800	    // Golden tag computed over the *unescaped* original text; if JSON escaping
801	    // changed the authenticated bytes, this value would not match.
802	    assert_eq!(
803	        rec.tag,
804	        "bfd39e8805a08d6cabbc2570d659bf746e7cbc0f49a714e8e9743eb710e80fac"
805	    );
806	    assert_eq!(rec.key_id, "kid-名字");
807	
808	    // The parsed record text must equal the input character for character.
809	    assert_eq!(rec.fields.len(), 1);
810	    assert_eq!(rec.fields[0], tricky);
811	
812	    // And the wire format must use standard JSON escapes without altering the
813	    // authenticated original (multibyte text stays as raw UTF-8).
814	    let raw = std::str::from_utf8(&out.stdout).unwrap();
815	    assert!(raw.contains("\\\""), "double quote must be escaped");
816	    assert!(raw.contains("\\\\"), "backslash must be escaped");
817	    assert!(raw.contains("\\n"), "newline must be escaped");
818	    assert!(raw.contains("\\r"), "carriage return must be escaped");
819	    assert!(raw.contains("\\t"), "tab must be escaped");
820	    assert!(raw.contains("\\u0001"));
821	    assert!(raw.contains("\\u0008"));
822	    assert!(raw.contains("\\u000c"));
823	    assert!(raw.contains("\\u001f"));
824	    assert!(raw.contains("中文🙂"), "printable Unicode must stay raw UTF-8");
825	    assert!(raw.contains('\u{7f}'), "DEL is not escaped by format 1 output");
826	
827	    // The raw key must not appear as a value anywhere in the record.
828	    let mut strings = Vec::new();
829	    rec.raw.strings(&mut strings);
830	    assert!(strings
831	        .iter()
832	        .all(|s| s.to_lowercase() != "00112233445566778899aabbccddeeff"));
833	}
