900	/// Run the same signing twice and return both records' parsed form plus the
901	/// exact stdout bytes, for determinism comparisons.
902	fn sign_twice(key: &str, key_id: &str, version: &str, fields: &[&str]) -> (Record, Record, Vec<u8>, Vec<u8>) {
903	    let out1 = run_sign(key, key_id, version, fields);
904	    let out2 = run_sign(key, key_id, version, fields);
905	    assert_eq!(out1.status.code(), Some(0));
906	    assert_eq!(out2.status.code(), Some(0));
907	    assert!(out1.stderr.is_empty() && out2.stderr.is_empty());
908	    (
909	        parse_single_record(&out1.stdout),
910	        parse_single_record(&out2.stdout),
911	        out1.stdout,
912	        out2.stdout,
913	    )
914	}
